use Illuminate\Support\Facades\DB;

// 詳細查 ClassSession id=3274
\$cs = DB::table('ClassSession')->where('id', 3274)->first();
echo '=== ClassSession 3274 ===\n';
echo json_encode(\$cs, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
echo '\n\n';

// 模擬 teacher=71 在 branch=9 下週 (4/20-4/26) 包含 Monday(4/20) 的完整 class-sessions
\$rows = DB::select(\"
    SELECT cs.id, cs.SessionDate, cs.StartTime, cs.Status, sc.StudentID, sc.TeacherID, 
           sub_sched.teacher_id as substitute_teacher_id,
           sub_sched.id as sub_sched_id,
           s.name as student_name
    FROM ClassSession cs
    JOIN StudentClass sc ON sc.ID = cs.StudentClassID
    JOIN Student s ON s.id = sc.StudentID
    LEFT JOIN (
        SELECT sub_inner.* FROM schedules sub_inner
        INNER JOIN (
            SELECT student_course_id, DATE(schedule_date) AS sched_date, start_time, MAX(id) AS max_id
            FROM schedules
            WHERE status = 'scheduled' AND original_schedule_id IS NOT NULL
            GROUP BY student_course_id, sched_date, start_time
        ) sub_latest ON sub_inner.id = sub_latest.max_id
    ) AS sub_sched 
        ON sub_sched.student_course_id = sc.ID
        AND DATE(sub_sched.schedule_date) = DATE(cs.SessionDate)
        AND sub_sched.start_time = SUBSTRING(cs.StartTime, 1, 5)
    WHERE (sc.TeacherID = 71 OR sub_sched.teacher_id = 71)
        AND s.CampusID IN (9, 3)
        AND cs.SessionDate BETWEEN '2026-04-20' AND '2026-04-26'
        AND cs.Status != 'cancelled'
    ORDER BY cs.SessionDate, cs.StartTime
\");
echo '=== Teacher=71 next week (non-cancelled, all branches) ===\n';
echo json_encode(\$rows, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
" 2>&1

